{"code": """"Token-guarded blueprint, migrated to FastAPI."""
from typing import Optional

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()
api = APIRouter(prefix="/api/v1")

_TOKENS = {"secret-token": {"user": "ana", "role": "admin"}}
_NOTES = {1: {"id": 1, "owner": "ana", "text": "first"}}


class Identity(BaseModel):
    user: str
    role: str


class Note(BaseModel):
    id: int
    owner: str
    text: str


def authenticate(
    x_api_token: Optional[str] = Header(default=None, alias="X-Api-Token"),
):
    if not x_api_token:
        return JSONResponse(
            status_code=401,
            content={"error": "missing token", "code": "AUTH_001"},
        )
    identity = _TOKENS.get(x_api_token)
    if identity is None:
        return JSONResponse(
            status_code=401,
            content={"error": "invalid token", "code": "AUTH_002"},
        )
    return identity


@api.get("/whoami", response_model=Identity)
def whoami(identity: dict = Depends(authenticate)):
    return Identity(user=identity["user"], role=identity["role"])


@api.get("/notes/{note_id}", response_model=Note)
def get_note(note_id: int, identity: dict = Depends(authenticate)):
    note = _NOTES.get(note_id)
    if note is None:
        raise HTTPException(status_code=404, detail="Not Found")
    if note["owner"] != identity["user"]:
        return JSONResponse(status_code=403, content={"error": "forbidden"})
    return note


@api.post("/notes", response_model=Note, status_code=201)
async def create_note(request: Request, identity: dict = Depends(authenticate)):
    data = {}
    try:
        body = await request.json()
        if isinstance(body, dict):
            data = body
    except Exception:
        pass

    text = data.get("text")
    if not text:
        return JSONResponse(
            status_code=422,
            content={"error": "text is required", "code": "VAL_001"},
        )
    return {"id": 2, "owner": identity["user"], "text": text}


app.include_router(api)
"}

{"code":""""Centralised error handling. Migrated from Flask to FastAPI.

Exercises: exception handlers for a custom exception and for HTTP exceptions,
manual 404/405 handling, and a uniform error envelope every client parses.
"""

from http import HTTPStatus

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field, ValidationError
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI()

_ACCOUNTS = {"a1": {"id": "a1", "balance": 100}}


class InsufficientFunds(Exception):
    def __init__(self, needed, available):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


class WithdrawRequest(BaseModel):
    amount: int = Field(gt=0, strict=True)


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds):
    return JSONResponse(
        status_code=409,
        content={"error": "insufficient_funds", "needed": exc.needed, "available": exc.available},
    )


@app.exception_handler(StarletteHTTPException)
async def on_http_error(request: Request, exc: StarletteHTTPException):
    message = HTTPStatus(exc.status_code).phrase
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": "http_error", "status": exc.status_code, "message": message},
    )


@app.get("/accounts/{account_id}")
async def get_account(account_id: str):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404, content={"error": "not_found", "resource": "account"}
        )
    return account


@app.post("/accounts/{account_id}/withdraw")
async def withdraw(account_id: str, request: Request):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404, content={"error": "not_found", "resource": "account"}
        )

    try:
        body = await request.json() or {}
    except Exception:
        body = {}

    try:
        data = WithdrawRequest.model_validate(body)
    except ValidationError:
        return JSONResponse(status_code=400, content={"error": "bad_amount"})

    amount = data.amount
    if amount > account["balance"]:
        raise InsufficientFunds(amount, account["balance"])

    return {"id": account_id, "withdrawn": amount, "balance": account["balance"] - amount}


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app)
"}}

